import{_ as e,o as r,c as s,a5 as i}from"./chunks/framework.CsGesDJn.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"feature/admin-management/3-10-6-view-user/report3_spec_en.md","filePath":"feature/admin-management/3-10-6-view-user/report3_spec_en.md"}'),a={name:"feature/admin-management/3-10-6-view-user/report3_spec_en.md"};function n(o,t,l,c,u,p){return r(),s("div",null,[...t[0]||(t[0]=[i("<p><strong>3.10.6 View User (User Directory, Filtering, Search &amp; Strike Counters)</strong></p><p><strong>Function Trigger</strong></p><p>Begins when an authenticated Administrator (ADMIN) navigates to /admin/users.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: ADMIN. Platform Administrator overseeing platform user accounts and membership governance.</li><li><strong>Purpose</strong>: Search and filter users by actual account status, system role, catalog plan and active strike state; show Agency roles separately.</li><li><strong>Interface</strong>: User Management Directory Screen (SCR-ADM-06), featuring search input, multidimensional filter dropdowns, tabulated data grid, and contextual action menus.</li><li><strong>Data Processing</strong>: Verify ADMIN, query paginated profiles with current status, activation flags and subscription catalog, and derive counters using FR 3.10.5 state instead of creation-time TTL.</li></ul><p><strong>Screen Layout</strong></p><p>Figure — User Management Directory Screen (SCR-ADM-06):</p><ul><li>Left/Header: Admin sidebar navigation; Top header with title &quot;User Governance Directory&quot; and user count summary badge.</li><li>Center: Search email/name; filters: ACTIVE, PENDING_VERIFICATION, FLAGGED, DEACTIVATED, DELETED and any retained legacy SUSPENDED state; ADMIN/USER; catalog plan; active strike severity. Rows show profile, system role, Agency ownership separately, current/pending plan, active YELLOW/ORANGE/RED counters, activation state and sanction end time. ORANGE threshold is x/3.</li><li>Buttons: Button &quot;+ Provision New User&quot; (primary button top right), Button &quot;Apply Filters&quot;, Button &quot;Reset Filters&quot;, Row three-dot action menu (View Details, Manage Violations &amp; Strikes, Edit Profile).</li><li>Footer: Pagination: 10/20/50 rows per page, page navigation and total count; default page size 20.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: None (defaults to page=1, limit=20, sortBy=createdAt, sortOrder=DESC).</li><li><strong>Input optional</strong>: page, limit, search, status, systemRole (ADMIN/USER), strikeFilter (ALL/HAS_YELLOW/HAS_ORANGE/HAS_RED/CLEAN), planId (catalog), sortBy, sortOrder.</li><li><strong>System data</strong>: users table, user_system_roles, workspace_members, subscription_plans, user_violations.</li><li><strong>Output</strong>: Paginated user list payload { items: [...], total, page, limit, totalPages } with HTTP 200 OK.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-63</strong>: Only ADMIN accesses the platform directory.</li><li><strong>BR-82</strong>: System roles are ADMIN and USER only. Agency/Workspace membership roles are managed separately. Subscription plan identifiers come from the existing catalog (currently BASIC, PRO, ENTERPRISE), not a second hardcoded catalog.</li><li><strong>BR-94</strong>: Use active/converted/pardoned/expired strike states from FR 3.10.5. Active counters and historical counts must not be confused; ORANGE displays x/3.</li><li><strong>BR-15</strong>: PENDING_VERIFICATION means email not verified. DEACTIVATED shows the sanction deadline. DELETED remains a separate self-service lifecycle.</li><li><strong>BR-65</strong>: Preserve pagination, search and filter URL state; allowlisted sorting and parameter validation are required. Never return password hashes, tokens or authenticator secrets.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>Missing ADMIN authority → MSG39.</li><li>No matching user accounts → empty table with MSG122.</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ol><li>Administrator navigates to /admin/users.</li><li>System validates ADMIN authorization (BR-35).</li><li>System queries database with default pagination parameters (page=1, limit=20).</li><li>System renders screen SCR-ADM-06 displaying user records, status pills, and active strike counters.</li><li>Administrator may enter search keywords or apply status / strike filters.</li><li>System recalculates query and updates the table instantaneously.</li></ol></li><li><p><strong>Abnormal Cases</strong></p><ul><li>1.a1: Missing ADMIN authority → MSG39.</li><li>5.a1: No matching users → empty state with MSG122; preserve current filters.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>Paginated directory reflects activation/sanction status, catalog plans and strike lifecycle consistently.</li><li>Search and filters remain in URL query parameters.</li></ul>",14)])])}const m=e(a,[["render",n]]);export{d as __pageData,m as default};
